COMMENT ON FUNCTION public.get_statistics_snapshot(text,uuid) IS 'Authenticated SECURITY DEFINER access is intentional: rejects anonymous/inactive callers; personal scope is auth.uid only; managerial scope requires server-side admin/facilitador role; membro community scope is limited to own teams. Returns metric fields only, no contact or CRM data. Linter 0029 reviewed.';
CREATE OR REPLACE FUNCTION public.validate_facilitator_designation() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.is_facilitator AND NOT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id=NEW.user_id AND role IN ('admin','facilitador','membro')) THEN RAISE EXCEPTION 'Promova a pessoa a Membro antes de designar Facilitador'; END IF; RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.validate_facilitator_designation() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER validate_facilitator_designation BEFORE INSERT OR UPDATE OF is_facilitator ON public.team_members FOR EACH ROW EXECUTE FUNCTION public.validate_facilitator_designation();